enum Ast {
  Lit(value: Int),
  Neg(inner: Ast),
  Bin(op: Str, left: Ast, right: Ast),
}

type Parsed {
  tree: Ast,
  next: Int,
}

fn is_digit(c: Str) -> Bool {
  return "0123456789".contains(c)
}

fn is_number(t: Str) -> Bool {
  return (not t.is_empty()) and is_digit(t.slice(0, 1))
}

fn tokenize(s: Str) -> Result[List[Str], Str] {
  let cs = s.chars()
  let n = cs.len()
  var toks: List[Str] = []
  var cur = ""
  var i = 0
  while i < n {
    let c = cs.get_or(i, "")
    if is_digit(c) {
      cur = cur + c
    } else {
      if cur != "" {
        toks = toks.push(cur)
        cur = ""
      }
      if c != " " {
        if "+-*/()".contains(c) {
          toks = toks.push(c)
        } else {
          return Err("syntax error")
        }
      }
    }
    i = i + 1
  }
  if cur != "" {
    toks = toks.push(cur)
  }
  return Ok(toks)
}

fn parse_primary(toks: List[Str], pos: Int) -> Result[Parsed, Str] {
  let t = toks.get_or(pos, "")
  if t == "(" {
    let inner = parse_expr(toks, pos + 1)?
    let closing = toks.get_or(inner.next, "")
    if closing != ")" {
      return Err("syntax error")
    }
    return Ok(Parsed { tree: inner.tree, next: inner.next + 1 })
  }
  if is_number(t) {
    return Ok(Parsed { tree: Ast.Lit(value: t.to_int().unwrap_or(0)), next: pos + 1 })
  }
  return Err("syntax error")
}

fn parse_factor(toks: List[Str], pos: Int) -> Result[Parsed, Str] {
  if toks.get_or(pos, "") == "-" {
    let inner = parse_factor(toks, pos + 1)?
    return Ok(Parsed { tree: Ast.Neg(inner: inner.tree), next: inner.next })
  }
  return parse_primary(toks, pos)
}

fn parse_term(toks: List[Str], pos: Int) -> Result[Parsed, Str] {
  let head = parse_factor(toks, pos)?
  var tree: Ast = head.tree
  var idx = head.next
  var op = toks.get_or(idx, "")
  while op == "*" or op == "/" {
    let rhs = parse_factor(toks, idx + 1)?
    tree = Ast.Bin(op: op, left: tree, right: rhs.tree)
    idx = rhs.next
    op = toks.get_or(idx, "")
  }
  return Ok(Parsed { tree: tree, next: idx })
}

fn parse_expr(toks: List[Str], pos: Int) -> Result[Parsed, Str] {
  let head = parse_term(toks, pos)?
  var tree: Ast = head.tree
  var idx = head.next
  var op = toks.get_or(idx, "")
  while op == "+" or op == "-" {
    let rhs = parse_term(toks, idx + 1)?
    tree = Ast.Bin(op: op, left: tree, right: rhs.tree)
    idx = rhs.next
    op = toks.get_or(idx, "")
  }
  return Ok(Parsed { tree: tree, next: idx })
}

fn parse_all(toks: List[Str]) -> Result[Ast, Str] {
  if toks.is_empty() {
    return Err("syntax error")
  }
  let whole = parse_expr(toks, 0)?
  if whole.next != toks.len() {
    return Err("syntax error")
  }
  return Ok(whole.tree)
}

fn eval_bin(op: Str, left: Ast, right: Ast) -> Result[Int, Str] {
  let a = eval_ast(left)?
  let b = eval_ast(right)?
  if op == "+" {
    return Ok(a + b)
  }
  if op == "-" {
    return Ok(a - b)
  }
  if op == "*" {
    return Ok(a * b)
  }
  if b == 0 {
    return Err("division by zero")
  }
  return Ok(a / b)
}

fn eval_ast(t: Ast) -> Result[Int, Str] {
  return match t {
    Ast.Lit(value) => Ok(value),
    Ast.Neg(inner) => eval_ast(inner).map(fn(v) => 0 - v),
    Ast.Bin(op, left, right) => eval_bin(op: op, left: left, right: right),
  }
}

pub fn calc(expr: Str) -> Result[Int, Str] {
  let toks = tokenize(expr)?
  let tree = parse_all(toks)?
  return eval_ast(tree)
}
